package ir.personal.smartfinance;

import android.app.*; import android.os.*; import android.content.*; import android.graphics.*; import android.net.Uri; import android.view.*; import android.widget.*; import org.json.*; import java.text.*; import java.util.*;

public class MainActivity extends Activity {
  LinearLayout root, content; EditText titleInput, amountInput, noteInput; Spinner typeSpinner; TextView summary; JSONArray entries; android.content.SharedPreferences prefs;
  int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+0.5f);} 
  TextView text(String s,int size){ TextView t=new TextView(this); t.setText(s); t.setTextSize(size); t.setTextColor(Color.rgb(35,45,60)); t.setPadding(dp(10),dp(8),dp(10),dp(8)); return t; }
  Button button(String s){ Button b=new Button(this); b.setText(s); b.setAllCaps(false); return b; }
  public void onCreate(Bundle b){super.onCreate(b); getWindow().getDecorView().setLayoutDirection(View.LAYOUT_DIRECTION_RTL); prefs=getSharedPreferences("finance",MODE_PRIVATE); try{entries=new JSONArray(prefs.getString("entries","[]"));}catch(Exception e){entries=new JSONArray();} showHome();}
  void base(String title){ root=new LinearLayout(this); root.setOrientation(1); root.setPadding(dp(12),dp(12),dp(12),dp(12)); root.setBackgroundColor(Color.rgb(246,248,251)); root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL); ScrollView sc=new ScrollView(this); content=new LinearLayout(this); content.setOrientation(1); content.setLayoutDirection(View.LAYOUT_DIRECTION_RTL); content.addView(text(title,24)); sc.addView(content); root.addView(sc,new LinearLayout.LayoutParams(-1,0,1)); setContentView(root); }
  void addBtn(String label,Runnable r){Button b=button(label); content.addView(b); b.setOnClickListener(v->r.run());}
  void save(){prefs.edit().putString("entries",entries.toString()).apply();}
  long num(String s){try{return Long.parseLong(s.replace(",","").replace("٬","").trim());}catch(Exception e){return 0;}}
  String money(long n){return String.format(java.util.Locale.US,"%,d",n)+" تومان";}
  long sum(String type){long x=0;for(int i=0;i<entries.length();i++){JSONObject o=entries.optJSONObject(i);if(o!=null&&type.equals(o.optString("type")))x+=o.optLong("amount");}return x;}
  void showHome(){base("حسابداری شخصی"); content.addView(text("داشبورد مالی • "+new SimpleDateFormat("yyyy/MM/dd  HH:mm",Locale.getDefault()).format(new Date()),14)); long inc=sum("درآمد"), exp=sum("هزینه"); content.addView(text("مجموع درآمد: "+money(inc),18)); content.addView(text("مجموع هزینه: "+money(exp),18)); content.addView(text("ماندهٔ ثبت‌شده: "+money(inc-exp),20)); addBtn("＋ ثبت درآمد یا هزینه",()->showAdd()); addBtn("📒 دفتر تراکنش‌ها",()->showEntries()); addBtn("📊 نمودار خلاصه",()->showChart()); addBtn("🖼 انتخاب عکس فاکتور / رسید",()->pickImage()); addBtn("🤖 دستیار مالی هوشمند",()->new AlertDialog.Builder(this).setTitle("دستیار مالی").setMessage("این نسخه هنوز به مدل هوش مصنوعی متصل نیست. برای افزودن پرسش‌وپاسخ هوشمند باید اتصال امن به سرویس AI و تنظیم کلید API انجام شود.").setPositiveButton("متوجه شدم",null).show()); addBtn("ℹ️ امکانات و محدودیت‌ها",()->new AlertDialog.Builder(this).setTitle("نسخهٔ آزمایشی").setMessage("این نسخه ثبت محلی درآمد و هزینه، محاسبهٔ جمع‌ها، تاریخ/ساعت دستگاه، نمودار ساده و انتخاب عکس را دارد. OCR فارسی، اسکن خودکار، مدیریت چک و اشخاص، PDF/چاپ و همگام‌سازی هنوز پیاده‌سازی نشده‌اند.").setPositiveButton("باشه",null).show()); }
  void showAdd(){base("ثبت تراکنش جدید"); typeSpinner=new Spinner(this); ArrayAdapter<String>a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"هزینه","درآمد"});typeSpinner.setAdapter(a);content.addView(text("نوع تراکنش",16));content.addView(typeSpinner); titleInput=new EditText(this);titleInput.setSingleLine();titleInput.setHint("عنوان (مثلاً خرید تجهیزات)");content.addView(titleInput);amountInput=new EditText(this);amountInput.setSingleLine();amountInput.setInputType(2);amountInput.setHint("مبلغ به تومان");content.addView(amountInput);noteInput=new EditText(this);noteInput.setHint("توضیحات (اختیاری)");content.addView(noteInput);addBtn("ذخیره تراکنش",()->{String title=titleInput.getText().toString().trim();long amount=num(amountInput.getText().toString());if(title.isEmpty()||amount<=0){Toast.makeText(this,"عنوان و مبلغ معتبر وارد کن",Toast.LENGTH_LONG).show();return;}JSONObject o=new JSONObject();try{o.put("type",typeSpinner.getSelectedItem().toString());o.put("title",title);o.put("amount",amount);o.put("note",noteInput.getText().toString());o.put("date",new SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.US).format(new Date()));entries.put(o);save();Toast.makeText(this,"ذخیره شد",Toast.LENGTH_SHORT).show();showHome();}catch(Exception e){Toast.makeText(this,"ذخیره انجام نشد",Toast.LENGTH_LONG).show();}});addBtn("بازگشت",()->showHome());}
  void showEntries(){base("دفتر تراکنش‌ها");if(entries.length()==0)content.addView(text("هنوز تراکنشی ثبت نشده است.",16));for(int i=entries.length()-1;i>=0;i--){JSONObject o=entries.optJSONObject(i);if(o!=null)content.addView(text(o.optString("type")+" — "+o.optString("title")+"\n"+money(o.optLong("amount"))+"\n"+o.optString("date")+(o.optString("note").isEmpty()?"":"\n"+o.optString("note")),16));}addBtn("بازگشت",()->showHome());}
  void showChart(){base("نمودار درآمد و هزینه");long in=sum("درآمد"),out=sum("هزینه");content.addView(text("نمودار مقایسه‌ای بر اساس تمام تراکنش‌های ثبت‌شده",14));content.addView(new View(this){Paint p=new Paint(3);protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight();p.setColor(Color.LTGRAY);c.drawRect(0,h*.15f,w,h*.85f,p);float max=Math.max(1,Math.max(in,out));p.setColor(Color.rgb(35,145,95));c.drawRect(w*.18f,h*.85f,w*.38f,h*.85f-(h*.65f*in/max),p);p.setColor(Color.rgb(220,90,80));c.drawRect(w*.58f,h*.85f,w*.78f,h*.85f-(h*.65f*out/max),p);p.setColor(Color.DKGRAY);p.setTextSize(dp(13));c.drawText("درآمد",(float)(w*.18),h*.97f,p);c.drawText("هزینه",(float)(w*.58),h*.97f,p);}} ,new LinearLayout.LayoutParams(-1,dp(220)));content.addView(text("درآمد: "+money(in)+"\nهزینه: "+money(out),16));addBtn("بازگشت",()->showHome());}
  void pickImage(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(i,101);}catch(Exception e){Toast.makeText(this,"انتخاب تصویر در دسترس نیست",Toast.LENGTH_SHORT).show();}}
  protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==101&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri u=data.getData();getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);new AlertDialog.Builder(this).setTitle("تصویر انتخاب شد").setMessage("تصویر انتخاب شد و می‌توان آن را برای بررسی دستی نگه داشت. استخراج خودکار متن فارسی از تصویر هنوز در این نسخه فعال نیست.\n\n"+u.toString()).setPositiveButton("باشه",(d,w)->showHome()).show();}}
  }
